mapper.select:

and source_name like concat('%', #{sourceName}, '%')
and source_type=#{sourceType}
and status=#{status}
and enabled=#{enabled}
 order by create_time desc


and source_name like concat('%', #{filter.sourceName}, '%')
and source_type=#{filter.sourceType}
and status=#{filter.status}
and enabled=#{filter.enabled}

  and (allowed_role_ids is null or allowed_role_ids=''
  or find_in_set(#{roleId},allowed_role_ids)>0)

 order by create_time desc

where id=#{id}

 and (allowed_role_ids is null or allowed_role_ids=''
 or find_in_set(#{roleId},allowed_role_ids)>0)



  and s.current_version_id=r.version_id
  and r.period=#{period}


      and (r.data_type='REPORT' or f.entity_type='FINANCIAL' or t.entity_type='FINANCIAL')
      and (r.data_type='NEWS' or f.entity_type='NEWS' or t.entity_type='NEWS')
      and r.data_type=#{dataType}


  and (r.from_entity_id=#{centerId} or r.to_entity_id=#{centerId})

    and (s.allowed_role_ids is null or s.allowed_role_ids=''
    or find_in_set(#{roleId},s.allowed_role_ids)>0)


order by r.id desc limit #{limit}


where r.chunk_id in
#{chunkId}

  and (s.allowed_role_ids is null or s.allowed_role_ids=''
  or find_in_set(#{roleId},s.allowed_role_ids)>0)

order by r.id desc limit #{limit}

select task_id taskId,question,source_type sourceType,include_news includeNews,status,progress,
current_stage currentStage,error_message errorMessage,create_time createdAt,started_time startedAt,finished_time finishedAt
from business_kb_qa_session
where task_owner=#{owner}
order by create_time desc limit #{limit}
